import heapq

class Node:
    def __init__(self, position, parent=None, g_cost=0, h_cost=0):
        self.position = position
        self.parent = parent
        self.g_cost = g_cost
        self.h_cost = h_cost
        self.f_cost = g_cost + h_cost

    def __lt__(self, other):
        return self.f_cost < other.f_cost

def heuristic(a, b):
    # Manhattan distance heuristic
    return abs(a.position[0] - b.position[0]) + abs(a.position[1] - b.position[1])

def a_star_search(maze, start, end):
    open_list = []
    closed_set = set()
    heapq.heappush(open_list, start)

    while open_list:
        current_node = heapq.heappop(open_list)
        if current_node == end:
            path = []
            while current_node:
                path.append(current_node.position)
                current_node = current_node.parent
            return path[::-1]

        closed_set.add(current_node.position)

        # Explore neighbors
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            neighbor = (current_node.position[0] + dx, current_node.position[1] + dy)
            if 0 <= neighbor[0] < len(maze) and 0 <= neighbor[1] < len(maze[0]) and maze[neighbor[0]][neighbor[1]] != 1:
                neighbor_node = Node(neighbor, current_node, g_cost=current_node.g_cost + 1)
                if neighbor_node.position in closed_set:
                    continue

                # Calculate heuristic cost
                neighbor_node.h_cost = heuristic(neighbor_node, end)
                neighbor_node.f_cost = neighbor_node.g_cost + neighbor_node.h_cost

                if neighbor_node not in open_list:
                    heapq.heappush(open_list, neighbor_node)
                else:
                    # Check if we found a better path to the neighbor
                    if neighbor_node.g_cost < open_list[open_list.index(neighbor_node)].g_cost:
                        open_list[open_list.index(neighbor_node)].parent = current_node
                        open_list[open_list.index(neighbor_node)].g_cost = neighbor_node.g_cost

    return []

